320	    /**
321	     * The calendar year in which {@code date}'s fiscal year starts. The fiscal year starts on
322	     * 1 July, so a date in July–December belongs to the fiscal year starting that calendar year,
323	     * while a date in January–June belongs to the fiscal year that started the previous calendar
324	     * year.
325	     */
326	    private static int fiscalYearStart(LocalDate date) {
327	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
328	    }
329	
330	    /**
331	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the last two digits of the
332	     * calendar year in which the fiscal year starts (the fiscal year starts on 1 July), derived
333	     * from the business-day-adjusted {@link #getRegistrationDate() registrationDate}
334	     * (e.g. a registration date in October 2026 yields {@code 'FY26'}). Not persisted — derived
335	     * from {@link #getRegistrationDate()}.
336	     */
337	    @Transient
338	    public String getFiscalYear() {
339	        return "FY" + String.format("%02d", fiscalYearStart(this.registrationDate) % 100);
340	    }
341	
342	    /**
343	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
344	     * the last two digits of the {@link #getFiscalYear() fiscal year} derived from the
345	     * business-day-adjusted {@link #getRegistrationDate() registrationDate}
346	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
347	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
348	     */
349	    @Transient
350	    public String getMembershipNumber() {
351	        return this.customerCode + "-M" + String.format("%02d", fiscalYearStart(this.registrationDate) % 100);
352	    }
353	
354	    /**
355	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
356	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
357	     * Not persisted — derived from {@link #getCustomerCode()}.
358	     */
359	    @Transient
360	    public int getCheckDigit() {
361	        int sum = 0;
362	        boolean dbl = true;
363	        String code = this.customerCode == null ? "" : this.customerCode;
364	        for (int i = code.length() - 1; i >= 0; i--) {
365	            char c = code.charAt(i);
366	            if (c < '0' || c > '9') {
367	                continue;
368	            }
369	            int d = c - '0';
370	            if (dbl) {
371	                d *= 2;
372	                if (d > 9) {
373	                    d -= 9;
374	                }
375	            }
376	            sum += d;
377	            dbl = !dbl;
378	        }
379	        return (10 - (sum % 10)) % 10;
380	    }
381	
382	    /**
383	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an
384	     * {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
385	     * namesakeCount} is {@code 0}; adds {@code 2} for a household of {@code 3} or more members
386	     * ({@link #getHouseholdSize() householdSize}); adds {@code 3} for a tenure of one or more
387	     * elapsed fiscal years since the {@link #getRegistrationDate() registration date}'s fiscal
388	     * year (the fiscal year starts on 1 July). Not persisted — derived from {@link #getEmail()},
389	     * {@link #getNamesakeCount()}, {@link #getHouseholdSize()} and {@link #getRegistrationDate()}.
390	     */
391	    @Transient
392	    public int getMembershipPoints() {
393	        int points = 0;
394	        boolean hasEmail = this.email != null && !this.email.isBlank();
395	        if (hasEmail) {
396	            points += 2;
397	        }
398	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
399	        if (uniqueName) {
400	            points += 1;
401	        }
402	        if (this.householdSize != null && this.householdSize >= 3) {
403	            points += 2;
404	        }
405	        if (this.registrationDate != null
406	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate) >= 1) {
407	            points += 3;
408	        }
409	        return points;
410	    }
411	
412	    /**
413	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()
414	     * membershipPoints}: {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
415	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more, then capped at
416	     * {@link #getMembershipLevelCap() membershipLevelCap} when one applies (a new owner's level
417	     * cannot exceed one above the maximum level among its existing household members). Not
418	     * persisted — derived from {@link #getMembershipPoints()} and {@link #getMembershipLevelCap()}.
419	     */
420	    @Transient
421	    public int getMembershipLevel() {
422	        int points = getMembershipPoints();
423	        int level;
424	        if (points >= 6) {
425	            level = 4;
426	        }
427	        else if (points >= 4) {
428	            level = 3;
429	        }
430	        else if (points >= 2) {
431	            level = 2;
432	        }
433	        else {
434	            level = 1;
435	        }
436	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
437	            return this.membershipLevelCap;
438	        }
439	        return level;
440	    }
441	
442	    /**
443	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
444	     */
445	    private static final Map<String, String> CITY_REGION = Map.of(
446	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
447	
448	    /**
449	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
450	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
451	     */
452	    private static final Map<String, int[]> REGION_RANGE = Map.of(
453	        "NSW", new int[] {2000, 2099},
454	        "VIC", new int[] {3000, 3099},
455	        "QLD", new int[] {4000, 4099});
456	
457	    /**
458	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
459	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
460	     */
461	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
462	        "NSW", "Australia/Sydney",
463	        "VIC", "Australia/Melbourne",
464	        "QLD", "Australia/Brisbane");
465	
466	    /**
467	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
468	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
469	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
470	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
471	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
472	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
473	     * by the owner pipelines (e.g. postcode validation) rather than copied.
474	     */
475	    public static String regionFor(String postcode, String city) {
476	        String region = regionForPostcode(postcode);
477	        if (region != null) {
478	            return region;
479	        }
480	        String cityRegion = regionForCity(city);
481	        return cityRegion != null ? cityRegion : "UNKNOWN";
482	    }
483	
484	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
485	     * Brisbane->QLD), or {@code null} when the city has no known region. */
486	    public static String regionForCity(String city) {
487	        return city == null ? null : CITY_REGION.get(city);
488	    }
489	
490	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
491	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
492	     * range. */
493	    public static String regionForPostcode(String postcode) {
494	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
495	            return null;
496	        }
497	        int value = Integer.parseInt(postcode);
498	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
499	            int[] range = entry.getValue();
500	            if (value >= range[0] && value <= range[1]) {
501	                return entry.getKey();
502	            }
503	        }
504	        return null;
505	    }
506	
507	    /**
508	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
509	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
510	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
511	     * derived from {@link #getCustomerCode()}.
512	     */
513	    @Transient
514	    public String getLocality() {
515	        if (this.customerCode == null) {
516	            return "UNKNOWN";
517	        }
518	        int dash = this.customerCode.indexOf('-');
519	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
520	    }
521	
522	    /**
523	     * The owner's timezone: the IANA name for the owner's {@link #getLocality() locality}/region
524	     * from the fixed region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
525	     * QLD->Australia/Brisbane), or {@code null} when the region has no mapped timezone. Not
526	     * persisted — derived from {@link #getLocality()}.
527	     */
528	    @Transient
529	    public String getTimezone() {
530	        return REGION_TIMEZONE.get(getLocality());
531	    }
532	
533	    /**
534	     * Whether more than 80 owners had already been created today when this response was
535	     * built. Not persisted — populated for the response by the create and fetch pipelines
536	     * and defaults to {@code false} so every owner serialization carries the flag.
537	     */
538	    @Transient
539	    public boolean isBulkSignupWarning() {
540	        return this.bulkSignupWarning;
541	    }
542	
543	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
544	        this.bulkSignupWarning = bulkSignupWarning;
545	    }
546	
547	    /**
548	     * Whether this owner's city already held between 40 and 49 owners when this response was
549	     * built, approaching the hard capacity limit of 50 (compared case-insensitively). Not
550	     * persisted — populated for the response by the create and fetch pipelines and defaults to
551	     * {@code false} so every owner serialization carries the flag.
552	     */
553	    @Transient
554	    public boolean isCapacityWarning() {
555	        return this.capacityWarning;
556	    }
557	
558	    public void setCapacityWarning(boolean capacityWarning) {
559	        this.capacityWarning = capacityWarning;
560	    }
561	
562	    /**
563	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
564	     * existing owner's last name and postcode with a different telephone. Not persisted —
565	     * populated for the response by the create and fetch pipelines and defaults to
566	     * {@code false} so every owner serialization carries the flag.
567	     */
568	    @Transient
569	    public boolean isPossibleDuplicate() {
570	        return this.possibleDuplicate;
571	    }
572	
573	    public void setPossibleDuplicate(boolean possibleDuplicate) {
574	        this.possibleDuplicate = possibleDuplicate;
575	    }
576	
577	    /**
578	     * The id of the existing owner this owner possibly duplicates (shared last name and
579	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
580	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
581	     */
582	    @Transient
583	    public Integer getPossibleDuplicateOf() {
584	        return this.possibleDuplicateOf;
585	    }
586	
587	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
588	        this.possibleDuplicateOf = possibleDuplicateOf;
589	    }
590	
591	    /**
592	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
593	     * is present, otherwise {@code 'PHONE'}.
594	     * Not persisted — derived from {@link #getEmail()}.
595	     */
596	    @Transient
597	    public String getContactPreference() {
598	        boolean hasEmail = this.email != null && !this.email.isBlank();
599	        return hasEmail ? "EMAIL" : "PHONE";
600	    }
601	
602	    /**
603	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
604	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
605	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
606	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
607	     * {@link #getRegistrationDate()}.
608	     */
609	    @Transient
610	    public String getAgeBand() {
611	        if (this.birthDate == null || this.registrationDate == null) {
612	            return null;
613	        }
614	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
615	        if (age < 18) {
616	            return "MINOR";
617	        }
618	        return age < 65 ? "ADULT" : "SENIOR";
619	    }
620	
621	    protected Set<Pet> getPetsInternal() {
622	        if (this.pets == null) {
623	            this.pets = new HashSet<>();
624	        }
625	        return this.pets;
626	    }
627	
628	    protected void setPetsInternal(Set<Pet> pets) {
629	        this.pets = pets;
630	    }
631	
632	    public List<Pet> getPets() {
633	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
634	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
635	        return Collections.unmodifiableList(sortedPets);
636	    }
637	
638	    public void setPets(List<Pet> pets) {
639	        this.pets = new HashSet<>(pets);
640	    }
641	
642	    public void addPet(Pet pet) {
643	        getPetsInternal().add(pet);
644	        pet.setOwner(this);
645	    }
646	
647	    /**
648	     * Return the Pet with the given name, or null if none found for this Owner.
649	     *
650	     * @param name to test
651	     * @return true if pet name is already in use
652	     */
653	    public Pet getPet(String name) {
654	        return getPet(name, false);
655	    }
656	
657	    /**
658	     * Return the Pet with the given name, or null if none found for this Owner.
659	     *
660	     * @param name to test
661	     * @return true if pet name is already in use
662	     */
663	    public Pet getPet(String name, boolean ignoreNew) {
664	        name = name.toLowerCase();
665	        for (Pet pet : getPetsInternal()) {
666	            if (!ignoreNew || !pet.isNew()) {
667	                String compName = pet.getName();
668	                compName = compName.toLowerCase();
669	                if (compName.equals(name)) {
670	                    return pet;
671	                }
672	            }
673	        }
674	        return null;
675	    }
676	
677	    public Pet getPet(Integer petId) {
678	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
679	    }
680	
681	    @Override
682	    public String toString() {
683	        return new ToStringCreator(this)
684	
685	            .append("id", this.getId())
686	            .append("new", this.isNew())
687	            .append("lastName", this.getLastName())
688	            .append("firstName", this.getFirstName())
689	            .append("address", this.address)
690	            .append("city", this.city)
691	            .append("telephone", this.telephone)
692	            .toString();
693	    }
694	}
